    if (!CryptGenKey(prov, CALG_RSA_2048, (2048 << 16) | CRYPT_EXPORTABLE, &rsa)) {
        CryptReleaseContext(prov,0); return -1;
    }
    DWORD blob_len = 0;
    CryptExportKey(rsa, 0, PUBLICKEYBLOB, 0, NULL, &blob_len);
    BYTE *pub_blob = malloc(blob_len);
    CryptExportKey(rsa, 0, PUBLICKEYBLOB, 0, pub_blob, &blob_len);
    DWORD priv_len = 0;
    CryptExportKey(rsa, 0, PRIVATEKEYBLOB, 0, NULL, &priv_len);
